-- VietABank Customer 360 POC - CRM_CUSTOMER (postgres)
-- Generated: 2026-11-27
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
BEGIN;

DROP TABLE IF EXISTS crm_customer;
CREATE TABLE crm_customer (
    cif TEXT,
    full_name TEXT,
    id_card TEXT,
    dob DATE,
    phone TEXT,
    email TEXT,
    address TEXT,
    segment TEXT,
    branch_id TEXT,
    department_id TEXT,
    portfolio_id TEXT,
    crm_balance NUMERIC(24,6),
    source_system TEXT,
    PRIMARY KEY (cif)
);
COMMIT;
